SINA_SMART["physio1-microbiota"] = {"lecture":"physio1-microbiota","title":"Intestinal microbiota","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-microbiota:e0","text":"Bacteria ~95% of the microbiota; Firmicutes and Bacteroidetes dominate.","topic":"Composition","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e1","text":"Density rises from stomach (low) to colon (~10¹²/g).","topic":"Composition","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e2","text":"SCFAs: acetate, propionate, butyrate (colonocyte fuel).","topic":"Functions","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e3","text":"Microbiota makes vitamin K and B vitamins; makes secondary bile acids.","topic":"Functions","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e4","text":"Colonisation resistance protects against pathogens.","topic":"Functions","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e5","text":"Microbiota matures GALT and shapes immune tolerance.","topic":"Functions","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e6","text":"Probiotics = live organisms; prebiotics = fibre; synbiotics = both.","topic":"Dysbiosis and therapy","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-microbiota:e7","text":"FMT: ~90% success in recurrent C. difficile infection.","topic":"Dysbiosis and therapy","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"g3bxqz":"a","1fevmx5":"a","akz0gd":"a","48eza2":"a","1ql31mp":"a","1t4v6ba":"a","jeb11i":"a","1j8zyur":"a","j5ogkr":"a","119s8zn":"a","1ok2yam":"a","mycu44":"x","12gnzpd":"x"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":2},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-microbiota:e0":{"s":0,"u":["Bacteria ~95% of the microbiota; Firmicutes and Bacteroidetes dominate.","Bacteria make up about 95%: Firmicutes (Lactobacillus, Clostridium, Enterococcus), Bacteroidetes (Bacteroides, Prevotella), Actinobacteria (Bifidobacterium), Proteobacteria (Escherichia, Helicobacter, Salmonella) and Verrucomicrobia ( Akkermansia muciniphila , mucus layer integrity)."],"dp":[]},"physio1-microbiota:e1":{"s":0,"u":["Density rises from stomach (low) to colon (~10¹²/g).","Density increases along the tract: stomach and duodenum low (acid; Lactobacillus, Helicobacter), jejunum and ileum more diverse, colon highest (about 10¹² bacteria per gram )."],"dp":[]},"physio1-microbiota:e2":{"s":1,"u":["SCFAs: acetate, propionate, butyrate (colonocyte fuel).","Metabolic : fermentation of fibre into short-chain fatty acids : acetate (energy), propionate (liver gluconeogenesis), butyrate (main fuel of colonocytes, anti-inflammatory); synthesis of vitamin K and B vitamins; conversion of primary into secondary bile acids ."],"dp":[]},"physio1-microbiota:e3":{"s":1,"u":["Microbiota makes vitamin K and B vitamins; makes secondary bile acids.","Metabolic : fermentation of fibre into short-chain fatty acids : acetate (energy), propionate (liver gluconeogenesis), butyrate (main fuel of colonocytes, anti-inflammatory); synthesis of vitamin K and B vitamins; conversion of primary into secondary bile acids ."],"dp":[]},"physio1-microbiota:e4":{"s":1,"u":["Colonisation resistance protects against pathogens.","Protection (colonisation resistance): competitive exclusion, bacteriocins and organic acids, support of the mucus layer."],"dp":[]},"physio1-microbiota:e5":{"s":1,"u":["Microbiota matures GALT and shapes immune tolerance.","Immune : maturation of GALT, tolerance to commensals, balance of IL-6/TNF-α and IL-10."],"dp":[]},"physio1-microbiota:e6":{"s":2,"u":["Probiotics = live organisms; prebiotics = fibre; synbiotics = both.","Tools to modulate the microbiota: probiotics (live beneficial organisms: Lactobacillus, Bifidobacterium, Saccharomyces boulardii ; used for antibiotic-associated and infectious diarrhoea), prebiotics (non-digestible fibres that feed beneficial bacteria: FOS in onions, garlic, bananas; GOS; inulin in chicory), synbiotics (both together), diet and exercise."],"dp":[]},"physio1-microbiota:e7":{"s":2,"u":["FMT: ~90% success in recurrent C. difficile infection.","Faecal microbiota transplantation : stool from a screened healthy donor given by colonoscopy, enema or capsules; about 90% success in recurrent Clostridioides difficile infection , with a risk of transmitting unknown pathogens."],"dp":[{"h":"Why antibiotics can cause colitis","t":"Broad-spectrum antibiotics wipe out much of the commensal colonic flora. Clostridioides difficile , which forms resistant spores, can then expand without competition and release toxins that cause diarrhoea and pseudomembranous colitis. Restoring a diverse microbiota by faecal transplantation removes the niche, which is why FMT works so well in recurrent infection: it is colonisation resistance put back."}]}},"meta":{"g3bxqz":{"a":"recall","vg":"physio1-microbiota:e0/recall/1"},"1fevmx5":{"a":"recall","vg":"physio1-microbiota:e1/recall/1"},"akz0gd":{"a":"recall","vg":"physio1-microbiota:e2/recall/1"},"48eza2":{"a":"recall","vg":"physio1-microbiota:e2/recall/2"},"1ql31mp":{"a":"recall","vg":"physio1-microbiota:e3/recall/1"},"1t4v6ba":{"a":"recall","vg":"physio1-microbiota:e0/recall/2"},"jeb11i":{"a":"recall","vg":"physio1-microbiota:e6/recall/1"},"1j8zyur":{"a":"recall","vg":"physio1-microbiota:e6/recall/2"},"j5ogkr":{"a":"recall","vg":"physio1-microbiota:e7/recall/1"},"119s8zn":{"a":"recall","vg":"physio1-microbiota:e4/recall/1"},"1ok2yam":{"a":"recall","vg":"physio1-microbiota:e3/recall/2"}},"explRev":"601c82c11fc1"};
